namespace sv_50e563f6b6b543c9bd50526ed2e6e1b7.Services;

/// <summary>
/// Scoped service (one per Blazor Server circuit) that holds the currently
/// selected warehouse and notifies all subscribed components when it changes.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    /// <summary>
    /// Raised on the calling thread whenever the warehouse changes.
    /// Components should call <see cref="ComponentBase.StateHasChanged"/>
    /// (or <c>InvokeAsync(StateHasChanged)</c>) inside their handler.
    /// </summary>
    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId)
            return;

        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_50e563f6b6b543c9bd50526ed2e6e1b7.Services;

/// <summary>
/// Scoped service (one per circuit) that provides low-stock alert data
/// and broadcasts change notifications so every subscribed component
/// re-renders when new data arrives — even if a different component
/// triggered the poll.
/// </summary>
public sealed class InventoryAlertService
{
    private static readonly Random s_random = Random.Shared;

    private int _lastCount;

    /// <summary>Current cached low-stock count.</summary>
    public int CurrentLowStockCount => _lastCount;

    /// <summary>
    /// Raised after <see cref="RefreshLowStockCountAsync"/> fetches new data.
    /// All subscribed components should re-render.
    /// </summary>
    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning the number of items below
    /// minimum stock levels for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate I/O latency + random result
        var count = s_random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches a fresh count and notifies all subscribers.
    /// Designed to be called by the polling component.
    /// </summary>
    public async Task RefreshLowStockCountAsync(string warehouseId)
    {
        _lastCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }
}

