@* Interactive island — the layout itself is static, but this component
   runs in InteractiveServer mode so it can handle change events. *@

@rendermode InteractiveServer
@implements IDisposable
@inject Services.WarehouseStateService WarehouseState

<select class="form-select form-select-sm"
        style="max-width:200px"
        value="@WarehouseState.CurrentWarehouseId"
        @onchange="OnWarehouseChanged">
    @foreach (var (id, name) in Services.WarehouseStateService.AvailableWarehouses)
    {
        <option value="@id">@name</option>
    }
</select>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
    }

    private void HandleStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
    }
}

@* Displays the current low-stock alert count as a Bootstrap badge.
   Subscribes to both WarehouseStateService (warehouse switch → immediate refresh)
   and InventoryAlertService (polling data arrives → re-render).
   Designed to work as an interactive island in the static NavMenu. *@

@rendermode InteractiveServer
@implements IDisposable
@inject Services.WarehouseStateService WarehouseState
@inject Services.InventoryAlertService AlertService

<span class="badge rounded-pill @BadgeClass">@AlertService.CurrentLowStockCount</span>

@code {
    private string BadgeClass => AlertService.CurrentLowStockCount switch
    {
        0 => "bg-success",
        <= 5 => "bg-warning text-dark",
        _ => "bg-danger"
    };

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleChange;
        AlertService.OnAlertCountChanged += HandleChange;
    }

    private void HandleChange() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleChange;
        AlertService.OnAlertCountChanged -= HandleChange;
    }
}

