@page "/dashboard"
@rendermode InteractiveServer
@implements IDisposable
@inject Services.WarehouseStateService WarehouseState
@inject Services.InventoryAlertService AlertService

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@WarehouseState.CurrentWarehouseName</p>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="card-text fs-4">
                    <span class="badge @BadgeClass">@AlertService.CurrentLowStockCount items</span>
                </p>
                <small class="text-muted">Refreshes every 10 seconds</small>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;

    private string BadgeClass => AlertService.CurrentLowStockCount switch
    {
        0 => "bg-success",
        <= 5 => "bg-warning text-dark",
        _ => "bg-danger"
    };

    protected override async Task OnInitializedAsync()
    {
        // Subscribe to external changes (warehouse switch, other components polling)
        WarehouseState.OnChange += HandleWarehouseChanged;
        AlertService.OnAlertCountChanged += HandleAlertChanged;

        // Initial fetch then start polling
        await AlertService.RefreshLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        StartPolling();
    }

    private void HandleWarehouseChanged()
    {
        // Restart polling for the new warehouse and fetch immediately
        StopPolling();
        InvokeAsync(async () =>
        {
            await AlertService.RefreshLowStockCountAsync(WarehouseState.CurrentWarehouseId);
            StartPolling();
        });
    }

    private void HandleAlertChanged() => InvokeAsync(StateHasChanged);

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshLowStockCountAsync(WarehouseState.CurrentWarehouseId);
                // OnAlertCountChanged already fires inside RefreshLowStockCountAsync,
                // so all subscribers (sidebar badge, this page) re-render automatically.
            }
        }
        catch (OperationCanceledException) { }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleWarehouseChanged;
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
        StopPolling();
    }
}

